import {test,before,after} from 'node:test';import assert from 'node:assert/strict';import {randomUUID as uid} from 'node:crypto';import {readFile} from 'node:fs/promises';import {spawnSync} from 'node:child_process';
import {isolatedModification,modificationMigration,modificationTables,read,write} from '../support/h4-modification-isolated.ts';import {modificationFixture} from '../support/h4-modification-fixtures.ts';import {H4011ModificationAdapter} from '../../src/infrastructure/postgres/h4-modification-adapter.ts';import type {ModificationCommand} from '../../src/domain/operational-modification.ts';import type {PostgresSql} from '../../src/infrastructure/postgres/transaction.ts';import {confirmationFixture} from '../support/h4-confirmation-fixtures.ts';import {requirementFixture} from '../support/h4-requirement-fixtures.ts';import {incidentFixture} from '../support/h4-incident-fixtures.ts';import {invoiceFixture} from '../support/h3-invoice-fixtures.ts';import {availabilityFixture} from '../support/h4-availability-fixtures.ts';import {holdFixture} from '../support/h4-hold-fixtures.ts';import {quantityFixture,nominalFixture} from '../support/h2-quantities-fixtures.ts';import {ownEconomicsFixture} from '../support/h3-own-economics-fixtures.ts';
let h:Awaited<ReturnType<typeof isolatedModification>>;before(async()=>{h=await isolatedModification('crm_h4012_sup',56602);});after(async()=>{await h?.close();});type M=Awaited<ReturnType<typeof modificationFixture>>;
const seed=async(stage='approve')=>{const m=await modificationFixture(h);await m.run(await m.request());if(stage!=='request')await m.run(await m.evaluate());if(stage==='approve')await m.run(await m.approve());return m;};
const snap=async(db:typeof h,names:string[])=>Promise.all(names.map(t=>db.observer.unsafe(`select coalesce(jsonb_agg(x order by x::text),'[]') d from (select to_jsonb(t) x from crm_private.${t} t) q`).then(r=>({table:t,data:r[0]!.d}))));
const inventory=async(db:typeof h)=>({tables:await db.observer`select c.oid,c.relowner,c.relacl,c.relrowsecurity,c.relforcerowsecurity from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname in ('crm_private','crm_api') order by c.oid`,functions:await db.observer`select p.oid,p.proowner,p.proacl,p.proconfig,p.prosecdef from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname in ('crm_private','crm_api') order by p.oid`,policies:await db.observer`select * from pg_policy order by oid`,triggers:await db.observer`select oid,tgrelid,tgname,tgfoid,tgtype,tgenabled,tgdeferrable,tginitdeferred from pg_trigger where not tgisinternal order by oid`,roles:await db.observer`select rolname,rolsuper,rolinherit,rolcreaterole,rolcreatedb,rolcanlogin,rolreplication,rolbypassrls from pg_roles order by rolname`});
async function race(jobs:(()=>Promise<unknown>)[],key:string,salt=31,reverse=false){const lock=await h.connect('crm_h0_migration').reserve();await lock.unsafe('begin');await lock`select pg_advisory_xact_lock(hashtextextended(${key},${salt}))`;const pending=Promise.allSettled((reverse?[...jobs].reverse():jobs).map(j=>j()));let overlap=false;try{for(let i=0;i<100;i++){if(Number((await h.admin`select count(*)::int n from pg_stat_activity where usename='crm_h0_runtime' and wait_event_type='Lock'`)[0]!.n)>=2){overlap=true;break;}await new Promise(r=>setTimeout(r,20));}}finally{await lock.unsafe('rollback');lock.release();}assert.ok(overlap,'two independent PostgreSQL sessions overlapping real lock waits');return pending;}
async function commands(m:M,a:ModificationCommand,b:ModificationCommand,reverse=false){const other=new H4011ModificationAdapter(h.connect('crm_h0_runtime'),h.f1,h.f2),auth=await h.auth();return race([()=>m.run(a),()=>other.apply(auth,write,b)],m.f.b.b.q.opportunityId,31,reverse);}
