test('H4-012 R16 fault every root history result canonical scope Task and actual COMMIT rolls back exact state',async()=>{for(const [table,deferred,action] of [['b06_modifications',false,'request'],['b06_modification_revisions',false,'apply'],['b06_modification_operations',false,'apply'],['b04_operational_versions',false,'apply'],['b07_pending_tasks',false,'evaluate'],['b06_modification_operations',true,'apply']] as const){const m=action==='request'?await modificationFixture(h):await seed(action==='evaluate'?'request':'approve'),q=action==='request'?await m.request():action==='evaluate'?await m.evaluate():await m.apply(),names=[...modificationTables,'b07_pending_tasks','b07_history','b07_operations','b04_bookings','b04_services','b04_contributions','b05_allocations'],old=await snap(h,names),reader=await h.booking.read(await h.auth(),read,m.bookingId);await h.admin.unsafe("create function crm_private.h4012_fault() returns trigger language plpgsql as $$begin raise exception 'SYNTHETIC_WRITE_OR_COMMIT_FAIL';end$$");await h.admin.unsafe(deferred?`create constraint trigger h4012_fault after insert on crm_private.${table} deferrable initially deferred for each row execute function crm_private.h4012_fault()`:`create trigger h4012_fault before insert on crm_private.${table} for each row execute function crm_private.h4012_fault()`);try{await assert.rejects(m.run(q));assert.deepEqual(await snap(h,names),old);assert.deepEqual(await h.booking.read(await h.auth(),read,m.bookingId),reader);}finally{await h.admin.unsafe(`drop trigger h4012_fault on crm_private.${table}`);await h.admin.unsafe('drop function crm_private.h4012_fault()');}await m.run(q);assert.ok(await m.see());}});
test('H4-012 R17 real COMMIT then lost response recovered durable without second cancellation/application',async()=>{const m=await seed(),q=await m.apply();let lose=true;const sql={begin:async(...args:Parameters<PostgresSql['begin']>)=>{const r=await h.runtime.begin(...args);if(lose){lose=false;throw new Error('SYNTHETIC_LOST_AFTER_COMMIT');}return r;}} as PostgresSql;await assert.rejects(new H4011ModificationAdapter(sql,h.f1,h.f2).apply(await h.auth(),write,q));assert.equal((await m.see())!.progress,'Aplicada');const n=(await m.see())!.history.length;assert.equal((await m.run(q)).replayed,true);assert.equal((await m.see())!.history.length,n);assert.equal((await h.observer`select count(*)::int n from crm_private.b04_operational_versions where booking_id=${m.bookingId}::uuid`)[0]!.n,1);});
test('H4-012 R12 disabled actor or revoked session denies read write and durable replay',async()=>{for(const mode of ['actor','session']){const u=await isolatedModification('crm_h4012_'+mode,mode==='actor'?56603:56604);try{const m=await modificationFixture(u),q=await m.request();await m.run(q);const prior=await u.auth();if(mode==='actor')await u.admin`update crm_private.crm_actors set enabled=false where actor_id=${u.actorId}::uuid`;else await u.admin`update crm_private.crm_sessions set revoked_at=clock_timestamp() where session_id=${u.sessionId}::uuid`;await assert.rejects(u.modifications.read(prior,read,m.modificationId,m.bookingId));await assert.rejects(u.modifications.apply(prior,write,q));}finally{await u.close();}}});
