test('H4-012 R18 populated42 upgrade Need INC AV Hold PC and all old data permissions intact',async()=>{const u=await isolatedModification('crm_h4012_upgrade',56605,true);try{const f=await confirmationFixture(u);await f.apply(await f.register());await f.apply(await f.evaluate());const r=await requirementFixture(u,f.b);await u.requirements.apply(await u.auth(),write,await r.need());await u.requirements.apply(await u.auth(),write,await r.receive());await u.requirements.apply(await u.auth(),write,await r.review());const i=await incidentFixture(u,f.b);await u.incidents.apply(await u.auth(),write,await i.detect());await u.incidents.apply(await u.auth(),write,await i.manage());const a=await availabilityFixture(u,f.b);await a.apply(await a.receive());await a.apply(await a.verify());const hold=await holdFixture(u);await hold.apply(await hold.grant());await hold.apply(await hold.check());const names=(await u.observer`select tablename from pg_tables where schemaname='crm_private' order by tablename`).map(x=>String(x.tablename)),old=await snap(u,names),catalog=await inventory(u);await u.migration.unsafe(await readFile('supabase/migrations/'+modificationMigration,'utf8'));assert.deepEqual(await snap(u,names),old);const next=await inventory(u);for(const k of ['tables','functions','policies','triggers'] as const){const ids=new Set(catalog[k].map(x=>x.oid));assert.deepEqual(Array.from(next[k]).filter(x=>ids.has(x.oid)),Array.from(catalog[k]));}assert.deepEqual(Array.from(next.roles),Array.from(catalog.roles));assert.equal((await r.see())!.status,'Revisado');assert.equal((await i.state())!.status,'En gestión');assert.equal((await a.assess())!.usable,true);assert.equal((await hold.assess())!.remaining,'12');assert.equal((await f.assess())!.usable,true);}finally{await u.close();}});
