for(const action of ['evaluate','provider','approve','reject','withdraw','change','review','review_negative','ratify','incident'] as const)test('H4-012 R16 every '+action+' transition fault at durable result preserves exact former scope and history',async()=>{const m=await seed(['withdraw','change','incident'].includes(action)?'approve':action==='evaluate'?'request':'evaluate');let q:ModificationCommand;if(action==='evaluate')q=await m.evaluate();else if(action==='approve')q=await m.approve();else if(action==='provider')q=await m.command(action,{partIds:[m.partId],commitment:'SYNTHETIC exact external commitment',recordId:null});else if(action==='reject'||action==='withdraw')q=await m.command(action,{decision:'SYNTHETIC verified decision',proofId:await m.f.proof('modification:no-pending-effects:'+m.modificationId,m.bookingId)});else if(action==='change'){const c=await m.request([{id:m.partId,scope:m.scope,expectedScopeRevision:1,desired:{date:'2026-10-23'},aspects:['date'],dependencies:[]}]);q=await m.attest({...c,action});}else if(action==='incident'){const i=await incidentFixture(h,m.f.b);await h.incidents.apply(await h.auth(),write,await i.detect());q=await m.command(action,{incidentId:i.incidentId,attempt:'SYNTHETIC test failed attempt',knownEffects:[],uncertainParts:[m.partId]});}else{const p=(await m.see())!.parts[0],aspects=['date'],validUntil='2030-01-01T00:00:00Z',claim='modification:ratify:'+await m.f.hash({part:Object.fromEntries(Object.entries(p!).filter(([k])=>k!=='review')),aspects,validUntil});q=await m.command(action,{partIds:[m.partId],aspects,validUntil,proofId:await m.f.proof(claim,m.bookingId),result:'SYNTHETIC checked scoped result'});}const old=await m.see(),reader=await h.booking.read(await h.auth(),read,m.bookingId),names=[...modificationTables,'b07_pending_tasks','b07_history','b07_operations'],data=await snap(h,names);await h.admin.unsafe("create function crm_private.h4012_transition_fault() returns trigger language plpgsql as $$begin raise exception 'SYNTHETIC_TRANSITION_FAIL';end$$");await h.admin.unsafe('create trigger h4012_transition_fault before insert on crm_private.b06_modification_operations for each row execute function crm_private.h4012_transition_fault()');try{await assert.rejects(m.run(q));assert.deepEqual(await m.see(),old);assert.deepEqual(await h.booking.read(await h.auth(),read,m.bookingId),reader);assert.deepEqual(await snap(h,names),data);}finally{await h.admin.unsafe('drop trigger h4012_transition_fault on crm_private.b06_modification_operations');await h.admin.unsafe('drop function crm_private.h4012_transition_fault()');}await m.run(q);assert.equal((await m.see())!.revision,old!.revision+1);});
